import{_ as s,o as t,c as i,a0 as e}from"./chunks/framework.Bogozrur.js";const k=JSON.parse('{"title":"跑通 RoboMaster 自瞄闭环仿真","description":"","frontmatter":{},"headers":[],"relativePath":"blog/2026-07-24-rm-simulation-setup.md","filePath":"blog/2026-07-24-rm-simulation-setup.md"}'),n={name:"blog/2026-07-24-rm-simulation-setup.md"};function l(p,a,d,o,h,r){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="跑通-robomaster-自瞄闭环仿真" tabindex="-1">跑通 RoboMaster 自瞄闭环仿真 <a class="header-anchor" href="#跑通-robomaster-自瞄闭环仿真" aria-label="Permalink to &quot;跑通 RoboMaster 自瞄闭环仿真&quot;">​</a></h1><p>今天完成了同济 SuperPower 25 赛季自瞄系统的 Windows 仿真复现。目标不是“让程序看起来在开火”，而是验证一条完整闭环：游戏画面进入视觉程序，程序检测并跟踪目标，外部命令真实带动云台，最后造成游戏内伤害。</p><p>最后一轮测试中，前哨站从剩余 440 HP 被击毁到 0 HP：发射 66 发，22 次造成有效伤害。这是今天最有价值的结果，因为它证明了外部视觉链路，而不是游戏内置 AI 的偶然行为。</p><h2 id="最终结果" tabindex="-1">最终结果 <a class="header-anchor" href="#最终结果" aria-label="Permalink to &quot;最终结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>结果</th></tr></thead><tbody><tr><td>外部瞄准认领</td><td><code>TargetMode=90</code>，验证通过</td></tr><tr><td>炮塔响应</td><td>测试角从 -90 度转到 45 度，实际变化 135 度</td></tr><tr><td>图像来源</td><td>游戏共享内存帧流正常，且帧写入进程身份匹配</td></tr><tr><td>不发射闭环</td><td>5,401 帧，检测率 92.0%，持续跟踪，无射击</td></tr><tr><td>第一轮开火</td><td>100 发，53 次有效伤害，HP 1500 到 440，命中率 53.0%</td></tr><tr><td>第二轮开火</td><td>66 发，22 次有效伤害，HP 440 到 0，击毁前哨站</td></tr><tr><td>安全交还</td><td>退出时确认 <code>AITargetMode</code> 已恢复，外控权已释放</td></tr></tbody></table><h2 id="我实际搭了什么" tabindex="-1">我实际搭了什么 <a class="header-anchor" href="#我实际搭了什么" aria-label="Permalink to &quot;我实际搭了什么&quot;">​</a></h2><p>项目运行在 Windows 上，复用真实 RoboMaster 自瞄的检测、PnP、跟踪、瞄准和射击模块，只把输入输出换成了游戏：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Gestalt 游戏渲染画面</span></span>
<span class="line"><span>  -&gt; 共享内存读取图像与同帧相机姿态</span></span>
<span class="line"><span>  -&gt; YOLO 检测装甲板</span></span>
<span class="line"><span>  -&gt; PnP 还原目标三维位置</span></span>
<span class="line"><span>  -&gt; EKF 估计旋转目标状态</span></span>
<span class="line"><span>  -&gt; Aimer 计算 yaw / pitch 与提前量</span></span>
<span class="line"><span>  -&gt; WebSocket 发送 RBExtAim</span></span>
<span class="line"><span>  -&gt; 游戏云台转动、开火、扣除目标 HP</span></span></code></pre></div><p>代码位置也很清楚：</p><table tabindex="0"><thead><tr><th>目录/文件</th><th>负责什么</th></tr></thead><tbody><tr><td><code>src/gestalt.cpp</code></td><td>仿真主程序，组织建模、接管、检测和测试流程</td></tr><tr><td><code>io/gestalt/</code></td><td>WebSocket 控制与共享内存取帧</td></tr><tr><td><code>tasks/auto_aim/</code></td><td>检测、跟踪、解算、瞄准、射击算法</td></tr><tr><td><code>configs/gestalt_sentry_outpost.yaml</code></td><td>前哨站基准场景的参数</td></tr></tbody></table><h2 id="关键排查-程序在动-不等于外控真的生效" tabindex="-1">关键排查：程序在动，不等于外控真的生效 <a class="header-anchor" href="#关键排查-程序在动-不等于外控真的生效" aria-label="Permalink to &quot;关键排查：程序在动，不等于外控真的生效&quot;">​</a></h2><p>今天最重要的坑在于，早期日志里已经能看到炮塔转动和伤害，但这还不足以证明外部自瞄接管成功。游戏自带 AI 也会扫描和开火，可能制造“好像跑通了”的假象。</p><p>真正的验收点是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>post-claim diag: TargetMode=90 ... verified=true</span></span>
<span class="line"><span>turret test result: before=-90.0 after=45.0 delta=135.0</span></span></code></pre></div><p>其中 <code>ExtAimClaim</code> 是对外部瞄准控制权的认领；<code>TargetMode=90</code> 表示游戏已把瞄准权交给视觉程序。之后主动发一个大角度命令并读取实际炮塔角度，才能确认命令确实改变了云台。</p><p>这个问题最终定位到游戏启动参数。游戏必须带：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-externalvisioncontrol -visionbridge -wsbind=127.0.0.1</span></span></code></pre></div><ul><li><code>-externalvisioncontrol</code>：开放最小的外部视觉控制白名单。</li><li><code>-visionbridge</code>：建立游戏画面的共享内存帧流。</li><li><code>-wsbind=127.0.0.1</code>：把控制 WebSocket 限制在本机。</li></ul><p>此外，控制端口每次启动可能不同，不能机械复用旧日志里的端口号。本次运行的 AttributeMap 控制端口是 <code>29662</code>；把错误端口传给桥程序，表面上能建立连接，却不会获得需要的状态和控制能力。</p><h2 id="从-c-语法到自瞄原理" tabindex="-1">从 C++ 语法到自瞄原理 <a class="header-anchor" href="#从-c-语法到自瞄原理" aria-label="Permalink to &quot;从 C++ 语法到自瞄原理&quot;">​</a></h2><p>我目前只学过 C++ 语法，因此把整件事拆成了下面几个可以逐步理解的问题。</p><h3 id="_1-yolo-在做什么" tabindex="-1">1. YOLO 在做什么 <a class="header-anchor" href="#_1-yolo-在做什么" aria-label="Permalink to &quot;1. YOLO 在做什么&quot;">​</a></h3><p>YOLO 输入一张图片，输出“哪些区域像装甲板”。它给出候选框、类别和置信度，但它不知道目标离我多远，也不会直接给云台角度。</p><h3 id="_2-pnp-为什么存在" tabindex="-1">2. PnP 为什么存在 <a class="header-anchor" href="#_2-pnp-为什么存在" aria-label="Permalink to &quot;2. PnP 为什么存在&quot;">​</a></h3><p>图像坐标是二维的，而云台需要朝三维空间里的目标转动。PnP 利用装甲板的真实尺寸、角点在图像中的位置，以及相机内参，推回目标相对相机的三维位置。</p><p>可以把它理解为：同一个装甲板在图像里更小，通常意味着它更远；但要把这种直觉变成可用坐标，必须经过相机模型计算。</p><h3 id="_3-ekf-为什么比单帧检测更可靠" tabindex="-1">3. EKF 为什么比单帧检测更可靠 <a class="header-anchor" href="#_3-ekf-为什么比单帧检测更可靠" aria-label="Permalink to &quot;3. EKF 为什么比单帧检测更可靠&quot;">​</a></h3><p>检测会抖动，也会偶尔漏掉装甲板。EKF 会保存对目标位置、速度和旋转状态的估计：有新检测时修正，没有检测时继续预测。</p><p>前哨站是旋转目标，本次日志稳定估计到角速度约 <code>2.51 rad/s</code>。这使系统不只是“看见以后再追”，而能预测装甲板下一刻会出现在哪里。</p><h3 id="_4-瞄准不是把准星对准当前画面" tabindex="-1">4. 瞄准不是把准星对准当前画面 <a class="header-anchor" href="#_4-瞄准不是把准星对准当前画面" aria-label="Permalink to &quot;4. 瞄准不是把准星对准当前画面&quot;">​</a></h3><p>子弹飞向目标需要时间，云台本身也有响应时间。因此真正的目标角度更接近：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>射击角度 = 目标在未来某一时刻的位置对应的角度</span></span></code></pre></div><p><code>Aimer</code> 负责把目标预测位置变成 yaw 和 pitch；<code>Shooter</code> 只在瞄准误差足够小时允许 <code>fire=true</code>。最后，<code>RBExtAim</code> 才把命令送进游戏。</p><h2 id="一次可复现的运行顺序" tabindex="-1">一次可复现的运行顺序 <a class="header-anchor" href="#一次可复现的运行顺序" aria-label="Permalink to &quot;一次可复现的运行顺序&quot;">​</a></h2><ol><li>启动游戏，并确保带上三个外部视觉参数。</li><li>找到这次游戏实例的 AttributeMap WebSocket 端口。</li><li>先运行 <code>--fire=0</code>：检查 <code>TargetMode=90</code>、炮塔响应、帧数和检测率。</li><li>再运行 <code>--fire=1</code>：检查 <code>shots</code>、目标 HP 和 <code>damage_dealt</code>。</li><li>退出时检查 <code>release_restored=true</code>，确认控制权交还给游戏。</li></ol><p>运行程序时还要把 vcpkg 与 OpenVINO DLL 目录放在 <code>PATH</code> 最前面；否则 Windows 可能加载到不兼容版本的运行库，表现为 <code>0xC0000139</code> 启动失败。</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PATH </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;C:\\dev\\vcpkg\\installed\\x64-windows\\bin;C:\\Users\\17859\\AppData\\Local\\Programs\\Python\\Python314\\Lib\\site-packages\\openvino\\libs;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PATH</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENCV_IO_ENABLE_OPENEXR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;0&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd C:\\Users\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">17859</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\sp_vision_25_gestalt_system_bridge</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\build\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gestalt.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws_port</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> configs\\gestalt_sentry_outpost.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fire</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">180</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">showui</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><h2 id="接下来怎么学" tabindex="-1">接下来怎么学 <a class="header-anchor" href="#接下来怎么学" aria-label="Permalink to &quot;接下来怎么学&quot;">​</a></h2><p>接下来不急着改复杂算法，先按这个顺序补基础：</p><ul><li>复跑一次不发射和开火测试，只观察日志与游戏画面。</li><li>从 <code>src/gestalt.cpp</code> 的主流程开始读，理解各阶段如何串联。</li><li>再读 <code>io/gestalt/game_link.cpp</code>，搞清 WebSocket、AttributeMap 和控制权。</li><li>最后进入 <code>tasks/auto_aim/</code>，依次看检测、PnP、EKF 和 Aimer。</li></ul><p>这样每补一个知识点，都能在已经跑通的系统中找到对应的位置。比起先硬啃完整代码，学习路径会更具体。</p><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>今天真正跑通的不是“一个会动的演示”，而是一条经过控制权、炮塔响应、图像来源和游戏伤害共同验证的自瞄闭环。</p>`,43)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
